import { HOSTED_DOMAIN_STATUSES, MAX_ADMIN_MAILBOX_BATCH } from '@hpc-mail/shared';
import {
  array, arrayOrPage, bool, boolFlag, changed, claimStrategy, clientRequestIdRule, conditionalDetail, describePaths, domainName, draftPaths, hostedDomainBatchPaths, hostedDomainPaths, identitiesDescription, int, listQuery,
  mailboxBatchPaths, mailboxListDescription, mailboxSearchQuery, mutationQuery, object, okResult, operation, optionalPageQuery, page, pageQuery, query, ref, syncQuery,
  scopeQuery, sendMailOperation, specInfo, specificationOperation, str, success, uploadPaths, usedExamples, usedSchemas, type Paths,
} from './openapi-common.js';
import { accountSessionPaths } from './openapi-account.js';
import { webhookPaths } from './openapi-webhooks.js';

/** Complete JWT-session contract; API keys are never accepted for these operations. */
export function buildSessionOpenApiSpec(origin: string) {
  const admin = { role: 'admin' as const };
  const hosted = hostedDomainPaths();
  const paths: Paths = {
    '/openapi.json': { get: specificationOperation() },
    '/config': { get: operation('getPublicConfig', 'Read public site configuration', ref('PublicConfig'), { errors: ['Internal'], public: true }) },
    '/avatar/{userId}': { get: operation('downloadAvatar', 'Download a public avatar', str, { public: true, binary: 'application/octet-stream', parameters: [query('v', str, 'Avatar version from avatarUrl; cache-busting value.') ] }) },
    '/auth/login': { post: operation('createSession', 'Sign in and create a JWT session', ref('LoginResponse'), { errors: ['BadCredentials', 'TotpRequired', 'UserDisabled', 'LoginRateLimited'], public: true, request: 'LoginRequest',
      description: 'If enabled, supply a six-digit TOTP or a recovery code in totp. Each TOTP code is accepted once; reusing it (or an older one) returns bad_credentials. A 401 error.code=totp_required means retry login with that code. The session token is different from an hpcm_ API key. New sessions are guarded against concurrent password/2FA changes.' }) },
    '/auth/register': { post: operation('registerUser', 'Register a user and create a session', ref('LoginResponse'), { errors: ['RegistrationClosed', 'InviteInvalid', 'UsernameTaken', 'RegisterRateLimited'], public: true, request: 'RegisterRequest', status: 201,
      description: 'Subject to closed/invite/open registration policy and IP limits. Invite mode requires inviteCode.' }) },
    '/auth/me': { get: operation('getCurrentUser', 'Read the current session user', ref('SessionUser')) },
    '/auth/avatar': {
      post: operation('uploadAvatar', 'Upload a base64 avatar', ref('SessionUser'), { errors: ['AvatarTooLarge'], request: 'UploadAvatarRequest' }),
      delete: operation('deleteAvatar', 'Delete the current user avatar', ref('SessionUser')),
    },
    '/auth/password': { put: operation('changePassword', 'Change password and replace the session', ref('ChangePasswordResponse'), { errors: ['ReauthFailed', 'ReauthRateLimited'], request: 'ChangePasswordRequest',
      description: 'Supply the current password in oldPassword; a wrong one returns 403 reauth_failed and shares the re-authentication limit (429 after 5 failures in 15 minutes). Changes password and credential epoch atomically, invalidates previous user JWTs, and returns a replacement JWT. Use the new token for subsequent calls. revokeApiKeys defaults to true and revokes every unrevoked API key of the user in the same change; revokedApiKeys reports how many. Revoked keys then return 401 on /v1.' }) },
    '/auth/2fa/setup': { post: operation('startTwoFactorSetup', 'Begin TOTP enrollment', object({ secret: str, otpauthUri: str }),
      { errors: ['TwoFactorAlreadyEnabled', 'ReauthRequired', 'ReauthFailed', 'ReauthRateLimited'], request: 'SetupTwoFactorRequest', example: { secret: 'JBSWY3DPEHPK3PXP', otpauthUri: 'otpauth://totp/HPC%20Mail:alice?secret=JBSWY3DPEHPK3PXP&issuer=HPC%20Mail' },
        description: 'Requires the current password (403 reauth_required when missing, 403 reauth_failed when wrong, 429 after 5 failures in 15 minutes). Returns a sensitive enrollment secret and QR-compatible otpauth URI; this does not enable TOTP until /auth/2fa/enable succeeds.' }) },
    '/auth/2fa/enable': { post: operation('enableTwoFactor', 'Verify TOTP and enable two-factor authentication', object({ recoveryCodes: array(str), token: str }),
      { errors: ['WrongTotpCode', 'TwoFactorAlreadyEnabled'], example: { recoveryCodes: ['k3j9-x8m2-p4q7', 'z1n5-w6r8-t2y4'], token: 'eyJhbGciOiJIUzI1NiJ9.e30.c2ln' }, request: 'EnableTwoFactorRequest', status: 201,
        description: 'Supply the six-digit code for the current enrollment secret; a wrong code returns 400 validation_failed. Recovery codes are returned once; store securely. Enabling invalidates every other session of the user; token replaces the current JWT and must be used for subsequent calls. The code used here cannot be reused to log in. This route is available when totp_setup_required restricts other actions.' }) },
    '/auth/2fa/disable': { post: operation('disableTwoFactor', 'Disable two-factor authentication', object({ success: { const: true, type: 'boolean' }, token: str }),
      { errors: ['ReauthRequired', 'ReauthFailed', 'ReauthRateLimited'], example: { success: true, token: 'eyJhbGciOiJIUzI1NiJ9.e30.c2ln' }, request: 'DisableTwoFactorRequest',
        description: 'Requires the current password; TOTP or recovery codes cannot disable 2FA. Disabling an enabled 2FA invalidates every other session; token replaces the current JWT.' }) },
    '/auth/logout': { post: operation('revokeSession', 'Revoke the current session', success) },
    '/domains': { get: operation('listDomains', 'List configured domains visible to this user', array(str), { example: ['example.org', 'alice.dev'], description: 'Returns data as an array, unlike /v1/domains data.domains. Ordinary users see public domains or the domains allowed by their dedicated mailboxPolicy. Dedicated policies replace public visibility and quotas; explicitly granted private domains are allowed. Active hosted domains follow the system domains: those the caller owns or was granted, or every active hosted domain for administrators, who may claim addresses on any user’s hosted domain. Adding/managing system domains requires administrator settings; users host their own domains with /hosted-domains; claiming an address is a separate operation.' }) },
    '/identities': { get: operation('listSenderIdentities', 'List sender identities', ref('SendIdentities'), { description: identitiesDescription }) },
    ...hosted,
    ...hostedDomainBatchPaths(),
    '/hosted-domains/{id}': {
      ...hosted['/hosted-domains/{id}'],
      put: operation('updateHostedDomain', 'Set the per-member claim limit', ref('HostedDomain'), { errors: ['HostedOwnerOnly'], request: 'UpdateHostedDomainRequest', description: 'Owner or administrator.' }),
      delete: operation('deleteHostedDomain', 'Stop hosting and delete the domain', success, { errors: ['HostedOwnerOnly', 'HostedStateChanged'],
        description: 'Owner or administrator. Irreversible: the domain enters deleting, rejects mail immediately, then every message on the domain is permanently deleted, all its addresses are released and the Cloudflare zone is removed. Restore the original nameservers at the registrar first or the domain stops resolving. Before deleting, the zone is read back and must match this domain and not predate the record (a mismatch or a system domain is never deleted and shows in lastError). The teardown counts 3 calls toward the site-wide Cloudflare budget but is never refused for it.' }),
    },
    '/hosted-domains/{id}/members': {
      get: operation('listHostedDomainMembers', 'List members of a hosted domain', array(ref('HostedDomainMember')), { errors: ['HostedOwnerOnly'], description: 'Owner or administrator.' }),
      put: operation('replaceHostedDomainMembers', 'Replace the members of a hosted domain', array(ref('HostedDomainMember')), { errors: ['HostedOwnerOnly', 'HostedStateChanged'], request: 'ReplaceHostedDomainMembersRequest',
        description: 'Owner or administrator. Members may claim addresses on the domain (subject to memberLimit and reserved prefixes) and only see mail of addresses they claimed. userIds replaces the whole list; removed members keep addresses they already claimed. expectedOwnerId must be the current owner, otherwise 409. Find users with GET /mailboxes/share-users.' }),
    },
    '/hosted-domains/{id}/members/{userId}': { delete: operation('removeHostedDomainMember', 'Remove a member or leave a shared domain', success, { errors: ['HostedOwnerOnly'],
      description: 'Owner or administrator removes any member; a member may remove themselves. Their claimed addresses are kept.' }) },
    '/hosted-domains/{id}/transfer': { post: operation('transferHostedDomain', 'Transfer a hosted domain to another user', ref('HostedDomainTransferResult'), { errors: ['HostedTransferLimit', 'HostedStateChanged'], request: 'TransferHostedDomainRequest',
      description: 'Owner or administrator. The target must be an active user; ordinary owners are limited by the target’s hosted_domains.maxPerUser. includeMailboxes moves the previous owner’s addresses on the domain with all history and revokes their mailbox shares. Members are kept. A stale expectedOwnerId returns 409; retrying a completed transfer returns transferred=false.' }) },
    '/mailboxes': {
      get: operation('listMailboxes', 'List caller-owned mailboxes', arrayOrPage(ref('Mailbox')), { parameters: [query('all', boolFlag, 'Administrator all=1 or true includes all owners; ordinary users cannot request this range.'),
        ...mailboxSearchQuery, ...optionalPageQuery], description: mailboxListDescription }),
      post: operation('claimMailbox', 'Claim an address on a configured domain', ref('Mailbox'), { errors: ['AddressTaken', 'ClaimQuota', 'ClaimDomainForbidden', 'ClaudeSuspended'], request: 'ClaimMailboxRequest', status: 201,
        description: 'Claim only a domain returned by /domains. Existing history at the address becomes visible to the claimant. Ordinary users obey their effective public or dedicated domain/global/per-domain quotas and system reserved-prefix restrictions. Dedicated policies do not revoke existing owned mailboxes. Does not provision a domain or Email Routing. Optional strategy=claude rejects any historical Claude suspension with 403 forbidden, including for administrators and hosted domains; checked atomically at insertion. Omitted or uniform preserves ordinary claims.' }),
    },
    '/mailboxes/shared': { get: operation('listSharedMailboxes', 'List inboxes shared with the caller', array(ref('SharedMailbox')), { description: 'Read-only inbound access; no sending, deletion or owner notifications. The read state of shared mail belongs to the owner: readers cannot change it, and it is excluded from their unread count and unread=1 list filter. Stars are personal.' }) },
    '/mailboxes/shares': {
      get: operation('listMailboxShares', 'List grants on caller-owned mailboxes', array(ref('MailboxShareGrant'))),
      put: operation('replaceMailboxShares', 'Replace grants on a caller-owned mailbox', ref('MailboxShareGrant'), { errors: ['ShareOwnMailboxOnly', 'ShareToOwner', 'MailboxOwnerChanged'], request: 'ReplaceMailboxSharesRequest',
        description: 'Owner JWT only; cannot manage another owner through this endpoint, even as an administrator. userIds replaces the entire list; [] revokes all. At most 100 unique active users, including administrators, excluding the mailbox owner. expectedOwnerId is optional and returns 409 if ownership changed. Shares grant only existing and future non-deleted inbound mail; no send/delete/read-state/notification rights. Use administrator endpoints to manage any owner.' }),
    },
    '/mailboxes/shares/batch': { post: operation('shareMailboxes', 'Add the same grantees to several caller-owned mailboxes', array(ref('MailboxShareGrant')), { errors: ['ShareOwnMailboxOnly', 'ShareListChanged'], request: 'BatchShareMailboxesRequest',
      description: 'Owner JWT only; every mailboxId must be owned by the caller, even for administrators, otherwise 403 and nothing is written. Appends: each userId is added to every mailbox, existing grantees keep their grantedAt, and nobody is removed, so retries are idempotent. Duplicate ids are ignored. userIds must be existing active users or administrators other than the caller; each mailbox may end with at most 100 grantees. All or nothing: every error leaves all mailboxes unchanged. 400 covers the caller in userIds, missing or disabled users, and a mailbox that would exceed 100 grantees after the append. Ownership, recipient status and the limit are rechecked in the same transaction as the write; 409 means state changed after validation, for example a mailbox was transferred or released, a recipient was disabled or deleted, or concurrent writes pushed a mailbox past 100 grantees. Concurrent grants or replacements by themselves are not rejected: they are merged in order, skipping grantees already present. Returns each mailbox’s full list as of this write, in the order of the deduplicated mailboxIds; a repeated id appears once. Use PUT /mailboxes/shares to replace or shrink a list.' }) },
    '/mailboxes/shares/{mailboxId}/grantees/{userId}': { delete: operation('revokeMailboxShare', 'Revoke one grantee on a caller-owned mailbox', success) },
    '/mailboxes/share-users': { get: operation('searchShareUsers', 'Search active users for mailbox sharing', ref('UserSearchResults'), {
      parameters: [query('q', { type: 'string', minLength: 1, maxLength: 32 }, 'Required username substring; trimmed and case-insensitive.', true),
        query('excludeUserId', { type: 'integer', minimum: 1 }, 'Exclude the mailbox owner.'),
        query('limit', { type: 'integer', minimum: 1, maximum: 20, default: 20 })],
      description: 'JWT only. Returns only id and username for active candidates (no role, so the search cannot be used to locate administrators); no account details or mailbox lists. hasMore means refine the search.'
    }) },
    ...mailboxBatchPaths(),
    '/mailboxes/availability': { get: operation('checkMailboxAvailability', 'Check mailbox availability', ref('MailboxAvailability'), { parameters: [query('localPart', str, undefined, true), query('domain', str, undefined, true), query('strategy', claimStrategy)],
      description: 'Advisory only, not a reservation. Same rules as claiming; when available=false, reason is taken, reserved, quota, domain_limit, domain_unavailable or claude_suspended. Claim still re-checks everything.' }) },
    '/mailboxes/{id}': {
      put: operation('updateMailbox', 'Set mailbox display name', ref('Mailbox'), { request: 'UpdateMailboxRequest', description: 'Mailbox owner or administrator only.' }),
      delete: operation('releaseMailbox', 'Release mailbox ownership', object({ success: bool, deletedMessages: int }), { parameters: [query('deleteHistory', boolFlag)],
        description: 'Default retains all address history for the next claimant. deleteHistory=1 atomically removes all existing address mail and ownership. Owner or administrator only. Previously delivered external links retain their promised 90-day validity.' }),
    },
    '/messages': { get: operation('listMessages', 'List mail with cursor pagination', ref('SessionMessagePage'), { parameters: listQuery, description: 'unread=1 matches only caller-claimed addresses; other views still include shared inbound mail. trash=1 items include deletedAt. Inbound summaries carry verificationLink (empty when none was detected).' }) },
    '/messages/sync': { get: operation('syncMessages', 'Poll unread count and first-page fingerprint', ref('MessageSync'), { parameters: syncQuery,
      description: 'Lightweight polling for the list view: accepts the same filters as GET /messages (cursor and afterId are ignored). Refetch the list only when head differs from the head returned with its first page.' }) },
    '/messages/send': { post: sendMailOperation() },
    '/messages/read': { post: operation('markMessagesRead', 'Mark selected owned messages read/unread',
      object({ changed: int, unread: { ...int, description: 'Only when includeUnread=true in the caller’s own view: unread count after this change, capped like GET /messages/unread-count.' } }, ['unread']),
      { request: 'ApiMarkReadRequest', parameters: mutationQuery,
        description: 'Changes only mail at addresses the caller owns (or unclaimed addresses with administrator scope=unclaimed). Shared mail is silently skipped; changed counts actual matches.' }) },
    '/messages/read-all': { post: operation('markAllMessagesRead', 'Mark incoming messages read, optionally narrowed by filters', changed, { parameters: mutationQuery, request: 'MarkAllReadRequest', requestRequired: false,
      description: 'Range is unread, non-trash inbound mail in the caller’s own claimed mailboxes (administrator scope=unclaimed: unclaimed addresses). Shared mail is never changed: its read state belongs to the owner. domain/address/q narrow it with the list search semantics. It never applies pagination.' }) },
    '/messages/delete': { post: operation('deleteMessages', 'Move selected messages to trash', object({ deleted: int }), { request: 'MessageIdsRequest', parameters: mutationQuery,
      description: 'Soft deletion. Restore before permanent deletion or the seven-day trash cleanup. Shared readers cannot delete mail.' }) },
    '/messages/restore': { post: operation('restoreMessages', 'Restore selected trashed messages', object({ restored: int, changed: int }), { request: 'MessageIdsRequest', parameters: mutationQuery }) },
    '/messages/purge': { post: operation('purgeMessages', 'Permanently delete selected trashed messages', object({ purged: int, changed: int }), { request: 'MessageIdsRequest', parameters: mutationQuery,
      description: 'Irreversible metadata removal. R2 cleanup failures are retried durably. Count reflects actual permitted deletions, not the input id count.' }) },
    '/messages/star': { post: operation('starMessages', 'Set per-user stars', changed, { request: 'StarMessagesRequest', parameters: mutationQuery }) },
    '/messages/unread-count': { get: operation('countUnreadMessages', 'Count unread inbox messages', object({ unread: int }), {
      description: 'Counts only addresses the caller claimed. Shared mail is excluded because its read state belongs to the owner. Counting stops at 1000 (1000 means at least 1000); /v1/messages/unread-count returns the exact value.' }) },
    '/messages/contacts': { get: operation('listRecentContacts', 'Read recent contact addresses', object({ contacts: array(str) }), { example: { contacts: ['bob@example.net', 'carol@example.com'] }, parameters: scopeQuery }) },
    '/messages/{id}': { get: conditionalDetail(operation('getMessage', 'Read full message detail', ref('MessageDetail'), { parameters: scopeQuery,
      description: 'replyTo supplies preferred reply targets; fall back to fromAddress. Attachment URLs are signed URLs aligned to the hour and valid for 1–2 hours; inline cid images in bodyHtml use the same URLs, so repeated reads within an hour return identical HTML. GET /attachments/{id} with the session token does not expire. Degraded mail has errorDetail; hasRaw reports archive availability.' }), 'hourly, like the URLs') },
    '/messages/{id}/thread': { get: operation('getMessageThread', 'Read a visible thread', object({ items: array(ref('MessageSummary')) }), { parameters: scopeQuery,
      description: 'Bounded thread view built from Message-ID/In-Reply-To/References. Without linking headers it falls back to the same address and normalized subject within 30 days, only when one side has a Re:/Fwd:/Fw:/回复:/转发: prefix and neither side carries a verification code.' }) },
    '/messages/{id}/translate': { post: operation('translateMessage', 'Translate text segments of a visible message to Simplified Chinese', ref('MessageTranslation'), { errors: ['TranslationDisabled', 'TranslationQuota', 'TranslationUnavailable'], request: 'TranslateMessageRequest', parameters: scopeQuery,
      description: 'JWT only; there is no /v1 equivalent. Returns 403 forbidden unless an administrator enabled translation and configured ai_model (see /config translationEnabled). Same visibility and scope/userId validation as message detail. Each segment is trimmed and whitespace-folded; only segments found in this message subject or full body (matching compares only letters and digits, ignoring HTML tags, entities, punctuation, whitespace and case) are sent to the configured external model, others are returned unchanged and counted in skipped. Segments without letters after removing URLs and email addresses (numbers, codes, punctuation) are returned unchanged and not billed. Identical segments are sent once. Results are cached per message and segment set: cached=true does not use quota. Each user has a daily character quota (settings.translation.dailyCharsPerUser, 0 unlimited; administrators included) and at most 30 model-calling requests per minute; exceeding either returns 429 rate_limited without consuming quota. A provider failure returns 500 and refunds the characters. Cached translations are deleted with the message.' }) },
    '/messages/{id}/raw': { get: operation('downloadRawMessage', 'Download the original .eml', str, { errors: ['NoRawArchive'], binary: 'message/rfc822', parameters: scopeQuery,
      description: 'Binary response without a data envelope; 404 when the message has no original archive.' }) },
    '/attachments/{id}': { get: operation('downloadAttachment', 'Download an attachment by session or signed URL', str, { errors: ['SignatureInvalid'], binary: 'application/octet-stream',
      parameters: [query('exp', { type: 'integer' }, 'Signed expiry, required together with sig for anonymous downloads.'), query('sig', str, 'HMAC signature; obtain the complete URL from message detail or an external email.'), ...scopeQuery],
      security: [{ sessionToken: [] }, { attachmentSignature: [], attachmentExpiry: [] }],
      description: 'JWT mode enforces the same visibility as message detail, including scope/userId: administrators reviewing another user pass scope=user&userId=, or scope=unclaimed for unclaimed addresses. Ordinary users get 403 for unclaimed/user and an invalid scope returns 400. Signed mode requires both exp and sig, ignores scope, and may serve retained external links after sent-mail deletion. Session-API message detail URLs are aligned to the hour and valid for 1–2 hours, so repeated reads within an hour return the same URL; /v1 detail URLs expire after 5 minutes. Returns binary bytes with safe MIME/download headers.' }) },
    ...uploadPaths(),
    ...draftPaths(),
    '/me/notify-prefs': {
      get: operation('getNotifyPrefs', 'Read masked personal notification and forwarding preferences', ref('NotifyPrefs')),
      put: operation('updateNotifyPrefs', 'Update personal notification and forwarding preferences', ref('NotifyPrefs'), { errors: ['PushKeyReentryRequired', 'ReauthRequired', 'ReauthFailed', 'ForwardConfirmLimit'], request: 'UpdateNotifyPrefsRequest',
        description: 'At least one channel. Forwarding targets: addresses already confirmed stay; each new address receives a confirmation mail (valid 72 hours, at most 20 such mails per user per day, 429 beyond) and is listed in forwardPending until its owner confirms, only then does forwarding to it start. Adding an address or enabling forwarding requires the current password in password (403 reauth_required / reauth_failed). ****** preserves stored secrets; explicit empty strings clear them. A ****** pushkey with a PushDeer endpoint whose origin or path changed (a trailing slash is ignored; empty means the official endpoint) returns 400 validation_failed until the pushkey is entered again. Enabled channels require complete valid configuration. Webhook is HPC Mail JSON ({event:"mail.received",message:{id,address,fromAddress,fromName,subject,verificationCode,verificationLink,preview,createdAt}}), not a native Bark/ntfy request. Email forwarding includes rate limits; shared readers never receive owner notifications.' }),
    },
    '/me/notify-prefs/health': { get: operation('getNotifyHealth', 'Read personal recent delivery health and forwarding quotas', ref('NotificationHealth'),
      { description: 'Current user only. pending/processing are queued; unknown means a result was not confirmed and must be checked before manual retry. Forward counts are attempts, and reset at UTC midnight. No message bodies or raw endpoint secrets are returned.' }) },
    '/me/notify-prefs/jobs/{id}/retry': { post: operation('retryNotification', 'Explicitly retry a failed or unknown personal notification', okResult,
      { errors: ['NotificationNotRetryable'], description: 'Owner-only failed/unknown mail notification jobs. Check actual receipt before retrying unknown results to avoid a duplicate. Forward/test records cannot use this endpoint. The selected channel must be enabled. Webhook has no automatic retry; this action is explicit.' }) },
    '/me/notify-prefs/feishu-test': { post: operation('testFeishuNotification', 'Send a real Feishu test with saved settings', okResult, { errors: ['NotificationTestFailed'], description: 'Performs an external notification and records its validated result. Failed delivery returns an error; this is not a dry run.' }) },
    '/me/notify-prefs/pushdeer-test': { post: operation('testPushDeerNotification', 'Send a real PushDeer test with saved settings', okResult, { errors: ['PushKeyMissing'], description: 'Performs an external notification and validates HTTP and provider JSON success. This is not a dry run.' }) },
    '/api-keys': {
      get: operation('listApiKeys', 'List own API keys without plaintext secrets', array(ref('ApiKeySummary'))),
      post: operation('createApiKey', 'Create an API key', ref('CreatedApiKey'), { errors: ['ApiKeyLimit', 'ReauthRequired', 'ReauthFailed', 'AdminScopeForbidden', 'AdminScopeRules'], request: 'CreateApiKeyRequest', status: 201,
        description: 'Requires the current password (password); missing returns 403 reauth_required, wrong returns 403 reauth_failed. The full key is returned only once. Scopes limit /v1 operations and never grant JWT-only functions (account settings, mail forwarding targets, 2FA, key management, administration). allowedMailboxIds/allowedDomains restrict the key to those mailboxes or domains; ids must be mailboxes the caller owns. The admin scope can only be granted by administrators and requires allowedIps plus an expiresAt at most 90 days ahead (400 otherwise; 403 for non-administrators); only with it does an administrator key act as administrator.' }),
    },
    '/api-keys/{id}': {
      get: operation('getApiKey', 'Read own API key metadata', ref('ApiKeySummary')),
      put: operation('updateApiKey', 'Update own API key limits/scopes/status', ref('ApiKeySummary'), { errors: ['AdminScopeForbidden', 'AdminScopeRules'], request: 'UpdateApiKeyRequest',
        description: 'Only supplied fields change; allowedMailboxIds/allowedDomains replace the whole list. When scopes, allowedIps or expiresAt change, the resulting key is validated against the admin scope rules (allowlist and at most 90 days); renaming or disabling an existing key is not.' }),
      delete: operation('revokeApiKey', 'Revoke own API key', success),
    },
    '/api-keys/{id}/logs': { get: operation('listApiKeyLogs', 'Read own API key audit logs', page(ref('ApiRequestLog')), { parameters: pageQuery,
      description: 'Newest first. path is the normalized route. Rejected requests are recorded at most once per key per minute.' }) },
    '/admin/users': {
      get: operation('listUsers', 'List users', array(ref('AdminUser')), admin),
      post: operation('createUser', 'Create a user', ref('AdminUser'), { errors: ['UsernameTaken'], ...admin, request: 'CreateUserRequest', status: 201 }),
    },
    '/admin/users/search': { get: operation('searchUsers', 'Search active users for mailbox transfer', ref('UserSearchResults'), {
      ...admin, parameters: [query('q', { type: 'string', minLength: 1, maxLength: 32 }, 'Required username substring, trimmed and case-insensitive; % and _ are literal characters.', true),
        query('excludeUserId', { type: 'integer', minimum: 1 }, 'Exclude the mailbox current owner.'),
        query('limit', { type: 'integer', minimum: 1, maximum: 20, default: 20 })],
      description: 'Returns only active users with id, username and role. Exact matches are ranked first, then prefixes, then other substring matches. hasMore means refine q to narrow the results. This endpoint avoids returning all account details and mailbox lists.'
    }) },
    '/admin/users/{id}': {
      put: operation('updateUser', 'Change user role/status/password or mailbox policy', ref('AdminUser'), { errors: ['SelfDisable', 'LastAdmin', 'StalePolicyRevision'], ...admin, request: 'UpdateUserRequest',
        description: 'At least one field. Cannot disable self or remove the last active administrator. Password reset/disable revokes prior JWT epochs; a password reset also revokes every API key of the user and is audited. Role changes preserve mailbox shares. mailboxPolicy=null restores public rules; a dedicated policy contains perUserLimit and domains:[{domain,perUserLimit}], with 0 meaning unlimited and an empty domain list blocking new claims. Only configured system domains may be granted, including private ones. Changing mailboxPolicy requires expectedMailboxPolicyRevision from GET /admin/users; a stale revision returns 409. Existing mailboxes retain read/send access and count toward quotas. Administrators are exempt. Role changes also increment mailboxPolicyRevision.' }),
      delete: operation('deleteUser', 'Delete a user', success, { errors: ['SelfDelete', 'LastAdmin', 'UserOwnsHostedDomains'], ...admin, description: 'Cannot delete self or last active administrator. Releases owned mailboxes and revokes keys/shares; message history remains address-owned and may be inherited by later claimants.' }),
    },
    '/admin/mailboxes/{id}': { get: operation('getMailbox', 'Read any claimed mailbox', ref('Mailbox'), { ...admin,
      description: 'Administrator JWT only. Includes ownerUsername and messageCount; 404 when the mailbox does not exist.' }) },
    '/admin/mailboxes/{id}/transfer': { post: operation('transferMailbox', 'Transfer any existing mailbox to an active user', ref('MailboxTransferResult'), { errors: ['MailboxOwnerChanged', 'ClaimQuota'],
      ...admin, request: 'TransferMailboxRequest', description: 'Administrator JWT only. userId is the target owner; expectedOwnerId comes from GET /mailboxes?all=1. Transfers an existing mailbox directly, including another user’s mailbox. For ordinary users with a dedicated mailboxPolicy, obeys configured-domain visibility, reserved-prefix restrictions and dedicated total/per-domain quotas; violations return 400/403. Users inheriting public rules and administrators retain the force-transfer exemption. Quotas and target permission/domain revisions are rechecked atomically; concurrent changes can return 409. Preserves mailbox id, address, display name and all message/attachment history. Atomically changes ownership, revokes all old shares and records mailbox.transfer audit. A stale owner returns 409, unless the mailbox already belongs to the target: that retry returns transferred=false and does not revoke new shares. Disabled/missing users cannot receive a mailbox. Future mail uses the new owner’s notification preferences; existing receipt-time snapshots/jobs remain unchanged.'
    }) },
    '/admin/mailboxes/batch/claim': { post: operation('claimMailboxesForUser', 'Claim several addresses for a user', ref('BatchClaimMailboxResult'), { ...admin,
      request: 'AdminBatchClaimRequest', errors: ['NotFoundTargetUser'],
      description: `Administrator JWT only (API keys return 401). At most ${MAX_ADMIN_MAILBOX_BATCH} items. Claims for userId under that user’s own claim rules: domain grants, reserved prefixes and quotas; a hosted domain must be active and the user its owner or a member. Same semantics and response as POST /mailboxes/batch: in order, already-claimed addresses go to taken, the first other error stops the batch, keeps the addresses already claimed and is reported in stoppedBy. One mailbox.claim audit row per claimed address. 404 when the target user does not exist; 400 when they are disabled.` }) },
    '/admin/mailboxes/batch/release': { post: operation('releaseMailboxes', 'Release several mailboxes', ref('AdminMailboxBatchResult'), { ...admin,
      request: 'AdminBatchReleaseRequest', errors: ['BatchStateChanged'],
      example: { results: [{ address: 'alice@example.org', status: 'done', mailboxId: 12, ownerId: 3, error: null, deletedMessages: 0, revokedShares: 1 },
        { address: 'ghost@example.org', status: 'failed', mailboxId: null, ownerId: null, error: { code: 'not_found', message: '邮箱不存在' }, deletedMessages: 0, revokedShares: 0 }], done: 1, unchanged: 0, failed: 1 },
      description: `Administrator JWT only. At most ${MAX_ADMIN_MAILBOX_BATCH} items with distinct addresses (case-insensitive), otherwise 400 for the whole batch. Releases each claimed mailbox and revokes its shares; deleteHistory=true also permanently deletes all history of those addresses, in the same single transaction (use smaller batches for addresses with much history). An item with expectedOwnerId is skipped as failed conflict when the current owner differs. Per-item results: items that fail validation (not_found, conflict) do not stop the others; the rest commit together, and if ownership changed between reading and committing nothing is written and the response is 409 conflict, so simply retry. A retry after a timeout reports already released items as not_found.` }) },
    '/admin/mailboxes/batch/transfer': { post: operation('transferMailboxes', 'Transfer several mailboxes to one user', ref('AdminMailboxBatchResult'), { ...admin,
      request: 'AdminBatchTransferRequest', errors: ['NotFoundTargetUser', 'BatchStateChanged'],
      example: { results: [{ address: 'alice@example.org', status: 'done', mailboxId: 12, ownerId: 3, error: null, revokedShares: 1 },
        { address: 'team@example.org', status: 'unchanged', mailboxId: 14, ownerId: 4, error: null, revokedShares: 0 }], done: 1, unchanged: 1, failed: 0 },
      description: `Administrator JWT only. At most ${MAX_ADMIN_MAILBOX_BATCH} items with distinct addresses; every item needs expectedOwnerId. Same rules as POST /admin/mailboxes/{id}/transfer for each item: history is kept, old shares are revoked, and a target user with a dedicated mailboxPolicy is charged item by item against their quota on system domains. Items already owned by the target are unchanged. Per-item results with the same transaction rules as release: a state change before commit returns 409 and writes nothing. 404 when the target user does not exist; 400 when they are disabled.` }) },
    '/admin/mailboxes/batch/share': { post: operation('shareMailboxesAsAdmin', 'Share several mailboxes with the same users', ref('AdminMailboxBatchResult'), { ...admin,
      request: 'AdminBatchShareRequest', errors: ['GranteeMissing', 'BatchStateChanged'],
      example: { results: [{ address: 'alice@example.org', status: 'done', mailboxId: 12, ownerId: 3, error: null, addedShares: 2 }], done: 1, unchanged: 0, failed: 0 },
      description: `Administrator JWT only. At most ${MAX_ADMIN_MAILBOX_BATCH} items with distinct addresses. Appends userIds to each mailbox’s share list without removing anyone; the owner is never added and each mailbox keeps at most 100 grantees. Items whose users are all already listed are unchanged. Every userId must be an existing active user (otherwise 400 for the whole batch). Per-item results with the same transaction rules as release.` }) },
    '/admin/mailboxes/batch/unshare': { post: operation('unshareMailboxes', 'Remove the same users from several mailboxes', ref('AdminMailboxBatchResult'), { ...admin,
      request: 'AdminBatchShareRequest', errors: ['BatchStateChanged'],
      example: { results: [{ address: 'alice@example.org', status: 'done', mailboxId: 12, ownerId: 3, error: null, revokedShares: 2 }], done: 1, unchanged: 0, failed: 0 },
      description: `Administrator JWT only. Same body as /admin/mailboxes/batch/share. Removes userIds from each mailbox’s share list; items where none of them were listed are unchanged. Per-item results with the same transaction rules as release.` }) },
    '/admin/settings': {
      get: operation('getSettings', 'Read current settings and domain revision', ref('Settings'), admin),
      put: operation('updateSettings', 'Update validated settings with domain conflict protection', ref('Settings'), { errors: ['StaleDomainsRevision', 'KeyReentryRequired'], ...admin, request: 'UpdateSettingsRequest',
        description: 'Use expectedDomainsRevision from the latest GET when replacing domains. A stale revision returns 409. Domain changes control new claims; DNS/catch-all setup is external and existing owned mailbox routing persists. ai_model.apiKey is write-only: responses show ****** when configured and submitting ****** keeps the stored key, unless the baseUrl origin or path changes (a trailing slash is ignored), which returns 400 validation_failed until apiKey is entered again. Enabling translation requires a configured ai_model, checked against the merged result when both are submitted; code_extract.aiEnabled may stay on without a model (regex only).' }),
    },
    '/admin/settings/ai-model-test': { post: operation('testAiModel', 'Test the AI model with a fixed translation sample', ref('AiModelTestResult'), { errors: ['AiModelIncomplete', 'KeyReentryRequired', 'AiModelFailed'], ...admin, request: 'AiModelTestRequest', requestRequired: false,
      description: 'Performs one real Chat Completions call, in the translation JSON format, with the sample "Your verification code is 123456. It expires in 10 minutes." Omitted or empty fields, and apiKey ******, use the saved settings.ai_model values, but the saved apiKey is only sent to the saved baseUrl origin and path (a trailing slash is ignored): a changed baseUrl without a new apiKey returns 400 validation_failed. No feature needs to be enabled, so a model can be tested before saving it. Missing baseUrl/apiKey/model after resolution returns 400. A provider failure returns 500 with the HTTP status, timeout or invalid-response reason; the key is never echoed. Does not consume user translation quota.' }) },
    '/admin/settings/domain-claude-stats': { get: operation('listDomainClaudeStats', 'Per-domain Claude account statistics', array(ref('DomainClaudeStats')), { ...admin,
      description: 'One item per configured domain, in list order. Judged from official Claude/Anthropic mail by MIME From and subject; senders are not DKIM-verified. Facts are kept after mail is deleted and are refreshed every 5 minutes.' }) },
    '/admin/settings/domain-status': { get: operation('checkDomainStatus', 'Check public domain DNS onboarding', ref('DomainStatus'), { ...admin, parameters: [query('domain', str, undefined, true)],
      description: 'Checks MX/SPF via public DNS. Cannot prove the private Cloudflare catch-all target or end-to-end email delivery.' }) },
    '/admin/hosted-domains': { get: operation('listHostedDomainsAsAdmin', 'List all hosted domains', arrayOrPage(ref('HostedDomain')), { ...admin,
      parameters: [query('status', { type: 'string', enum: HOSTED_DOMAIN_STATUSES }), query('q', { type: 'string', maxLength: 253 }, 'Domain or owner username substring.'), ...optionalPageQuery],
      description: 'Ordered by id, newest first. Without cursor and limit the response is an array capped at 1000 items, as before; page with limit and nextCursor to see every domain. Administrators manage details, members, transfer and deletion through /hosted-domains/{id} with full rights.' }) },
    '/admin/hosted-domains/health': { get: operation('checkHostedDomainsHealth', 'Check hosted domain prerequisites', ref('HostedDomainsHealth'), { ...admin,
      description: 'Whether the Worker has Cloudflare credentials, whether the token verifies, and the account zone counts. Cloudflare blocks new zones when an account has more than 50 zones and more pending than active ones.' }) },
    '/admin/hosted-domains/{id}/suspend': { post: operation('suspendHostedDomain', 'Suspend a hosted domain', ref('HostedDomain'), { ...admin,
      description: 'Rejects incoming mail, blocks sending and new claims. Addresses and history are kept.' }) },
    '/admin/hosted-domains/{id}/resume': { post: operation('resumeHostedDomain', 'Resume a suspended hosted domain', ref('HostedDomain'), { ...admin,
      description: 'Re-checks Cloudflare immediately and returns to the matching state.' }) },
    '/admin/delivery-events': { get: operation('getDeliveryEvents', 'Read outbound delivery receipt subscriptions', ref('DeliveryEventsOverview'), { ...admin,
      description: 'The delivery_events switch, whether the Worker has Cloudflare credentials, the Queue name and the Cloudflare Email Sending event subscription of each sending domain. Creating subscriptions needs a Cloudflare token with Account Queues:Edit, and for system domains read access to the zone; failures appear in lastError. A subscription created by hand in Cloudflare for the same domain and Queue is detected and marked active on the next retry or daily check.' }) },
    '/admin/suppressions': { get: operation('listSuppressions', 'List active outbound suppressions', page(ref('EmailSuppression')), { ...admin,
      parameters: [query('q', { type: 'string', maxLength: 254 }, 'Case-insensitive substring of the recipient address or sending domain.'), ...pageQuery],
      description: 'Unexpired entries only, newest id first. Bounced and complained delivery receipts add entries per recipient address and sending domain; sends from that domain to the address fail with recipient_suppressed until the entry expires or is removed.' }) },
    '/admin/suppressions/{id}': { delete: operation('deleteSuppression', 'Remove a suppression entry', success, { ...admin,
      description: 'Removes the entry from this site’s list only, so the next send to the address is attempted again; confirm the address works first. Cloudflare keeps its own suppression list, which must be cleared separately in Cloudflare or sends are still rejected there. 404 not_found when the entry does not exist. Recorded in the administrator audit log as suppression.delete.' }) },
    '/admin/system-domains/zones': { get: operation('listSystemDomainZones', 'List Cloudflare zones that can be onboarded as system domains', ref('SystemDomainZonesView'), { errors: ['CloudflareCredentialsMissing', 'CloudflareBusy'], ...admin,
      parameters: [query('hidden', { type: 'string', enum: ['0', '1'], default: '0' }, '1 lists only hidden zones.'),
        query('refresh', { type: 'string', enum: ['0', '1'], default: '0' }, '1 bypasses the 60-second zone-list cache.')],
      description: 'Classifies every zone in the site Cloudflare account by D1 data: system (already in settings.domains.list), hosted (a user hosted domain; administrator-owned ones are flagged), onboarding (active task, shown inline), inconsistent (hosted record with another zone id) and available. Up to 10 visible available zones per request are prechecked (cached 60 seconds) and carry a readiness verdict; the rest are unchecked. Without Cloudflare credentials returns configured=false. Not controlled by the hosted_domains switch. Cloudflare calls count against a separate budget of 120 per 5 minutes; when exhausted or after a Cloudflare 429 the endpoint returns 429 rate_limited.' }) },
    '/admin/system-domains/precheck': { get: operation('getSystemDomainPrecheck', 'Precheck a system domain onboarding (read-only)', ref('SystemDomainPrecheck'), { errors: ['ZoneNotVisible', 'CloudflareCredentialsMissing'], ...admin,
      parameters: [query('mode', { type: 'string', enum: ['existing_zone', 'new_zone'] }, 'existing_zone uses a zone already in the Cloudflare account (no nameserver change); new_zone creates a zone and requires changing nameservers.', true),
        query('zoneId', { type: 'string', pattern: '^[0-9a-f]{32}$' }, 'Required for existing_zone.'), query('domain', domainName, 'Required for new_zone.')],
      description: 'Reads Cloudflare and D1 without writing. Business conflicts are not errors: they appear in checks with severity info, confirm (accept with ack) or blocker, and verdict summarizes them. A third-party or null MX on the apex is a dangerous confirmation (mx.delete): once accepted the site deletes those records and immediately enables Email Routing, so the domain stops receiving at the old provider. A catch-all owned by another Worker, forwarding or dropping needs catchAll.replace; a catch-all managed by another Worker’s wrangler addresses is a blocker. One existing SPF needs spf.merge; several SPF records, macros or more than 10 lookups block. Enabled address rules need rules.bypass; a missing _dmarc needs dmarc.create when the domain shows other mail services (otherwise info). Any read failure is a blocker (unknown is never treated as absent). new_zone always needs ns.change. 404 when zoneId is not visible to the site token.' }) },
    '/admin/system-domains/onboardings': {
      get: operation('listSystemDomainOnboardings', 'List system domain onboarding tasks', array(ref('SystemDomainOnboarding')), { ...admin,
        parameters: [query('active', { type: 'string', enum: ['0', '1'], default: '0' }, '1 lists only active tasks.'), query('limit', { type: 'integer', minimum: 1, maximum: 200, default: 100 })],
        description: 'Newest first, read from D1 only.' }),
      post: operation('createSystemDomainOnboarding', 'Onboard a domain as a system domain in one step', ref('SystemDomainOnboarding'), { errors: ['OnboardingNeedsConfirmation', 'ZoneNotVisible', 'CloudflareCredentialsMissing'], ...admin, request: 'CreateSystemDomainOnboardingRequest', status: 201,
        description: 'The server prechecks again. With no confirmation needed, or when accept covers every requiredAck and fingerprint matches, it creates the task and starts immediately: an active existing zone goes to configuring (SPF merge, catch-all to this Worker, deletion of accepted third-party MX immediately followed by enabling Email Routing, Email Sending), a pending zone is linked and waits for activation, and new_zone creates the zone and returns its nameServers. Otherwise it returns 409 conflict with error.details.precheck: confirm the listed items and retry with its fingerprint and accept; a blocker also returns 409. 201 creates a task; replaying the same domain and mode (and zoneId) while a task is active returns 200 with it. Three-way exclusion: a system domain, a hosted domain and an active task can never share a name. On completion the domain is appended to settings.domains.list as {public:false, perUserLimit:0, random:true}; adjust it with PUT /admin/settings. Mail arriving before completion is stored as unclaimed. Nothing is rolled back automatically; original values are in changes.' }),
    },
    '/admin/system-domains/onboardings/{id}': { get: operation('getSystemDomainOnboarding', 'Read a system domain onboarding task', ref('SystemDomainOnboarding'), { ...admin,
      description: 'Reads D1 only; progress is advanced by the 5-minute cron and by check.' }) },
    '/admin/system-domains/onboardings/{id}/check': { post: operation('checkSystemDomainOnboarding', 'Check or retry an onboarding task now', ref('SystemDomainOnboarding'), { errors: ['OnboardingFinished'], ...admin,
      description: 'Re-reads Cloudflare and continues where possible (requests a nameserver activation check while waiting). Within 15 seconds of the previous check, or while another worker holds the task, returns the current view without error. 409 for finished tasks.' }) },
    '/admin/system-domains/onboardings/{id}/confirm': { post: operation('confirmSystemDomainOnboarding', 'Confirm changes after the remote configuration changed', ref('SystemDomainOnboarding'), { errors: ['OnboardingNeedsConfirmation', 'UnconfirmedChanges', 'OnboardingNotAwaitingConfirmation', 'OnboardingBusy'], ...admin, request: 'ConfirmSystemDomainOnboardingRequest',
      description: 'Only for state needs_confirmation (usually the remote configuration drifted after the original confirmation). Sends the fingerprint and accept from task.precheck. A stale fingerprint returns 409 with the new precheck in error.details.precheck; accept missing a required item returns 400; a new blocker returns 409.' }) },
    '/admin/system-domains/onboardings/{id}/cancel': { post: operation('cancelSystemDomainOnboarding', 'Cancel an onboarding task', ref('SystemDomainOnboarding'), { errors: ['OnboardingFinished'], ...admin, request: 'CancelSystemDomainOnboardingRequest', requestRequired: false,
      description: 'Marks the task cancelled; the processor stops at its next checkpoint (state cancelling until then). deleteCreatedZone=true also deletes the zone only when this task created it and it never became active (canDeleteZone); otherwise 400. Linked or recovered zones are never deleted, and Cloudflare changes already made are not rolled back. 409 for finished tasks: remove a completed system domain from the list with PUT /admin/settings, which does not stop Cloudflare routing.' }) },
    '/admin/system-domains/hidden-zones': { put: operation('updateSystemDomainHiddenZones', 'Hide or show a zone in the onboarding list', ref('SystemDomainHiddenZones'), { errors: ['HiddenZonesChanged'], ...admin, request: 'UpdateSystemDomainHiddenZonesRequest',
      description: 'Hidden zones are recorded by domain name and listed with GET /admin/system-domains/zones?hidden=1. expectedRevision comes from hiddenRevision; a stale revision returns 409.' }) },
    '/admin/mailbox-shares': {
      get: operation('listMailboxSharesAsAdmin', 'List grants on all claimed mailboxes', arrayOrPage(ref('MailboxShareGrant')), { ...admin,
        parameters: [query('mailboxId', { type: 'integer', minimum: 1 }, 'Only this mailbox: always an array of at most one item; cursor and limit are ignored.'),
          query('q', { type: 'string', maxLength: 254 }, 'Case-insensitive literal substring of the address or the owner username (no wildcards).'), ...optionalPageQuery],
        description: 'Each item is one mailbox with its complete grantee list (grantees sorted by username). The full array is sorted by address; pages are ordered by mailbox id, newest first, and limit counts mailboxes, not grantees.' }),
      put: operation('replaceMailboxSharesAsAdmin', 'Replace grants on any claimed mailbox', ref('MailboxShareGrant'), { errors: ['ShareToOwner', 'MailboxOwnerChanged'], ...admin, request: 'ReplaceMailboxSharesRequest',
        description: 'Administrator JWT can share any claimed mailbox, including other users’ mailboxes, with any active user or administrator except the owner. Empty userIds revokes all shares. At most 100 grantees. expectedOwnerId optionally detects stale ownership with 409. The write also rechecks ownership and recipient status atomically. Owner metadata and grantee status are returned. Grants are read-only incoming mail; owner disable hides shares, role changes preserve them, and release/transfer/deletion revoke them.' }),
    },
    '/admin/mailbox-shares/{mailboxId}/grantees/{userId}': { delete: operation('revokeMailboxShareAsAdmin', 'Revoke one mailbox grantee', success, admin) },
    '/admin/invites': {
      get: operation('listInvites', 'List invitation codes and use history', array(ref('Invite')), admin),
      post: operation('createInvites', 'Create invitation codes', array(ref('Invite')), { ...admin, request: 'CreateInviteRequest', status: 201 }),
    },
    '/admin/invites/{id}': { delete: operation('revokeInvite', 'Revoke an invitation code', success, admin) },
    '/admin/api-keys': { get: operation('listApiKeysAsAdmin', 'List all API key metadata with owners', array(ref('ApiKeySummary')), admin) },
    '/admin/api-keys/{id}': {
      get: operation('getApiKeyAsAdmin', 'Read any API key metadata', ref('ApiKeySummary'), admin),
      delete: operation('revokeApiKeyAsAdmin', 'Revoke any API key', success, admin),
    },
    '/admin/api-keys/{id}/logs': { get: operation('listApiKeyLogsAsAdmin', 'Read any API key audit logs', page(ref('ApiRequestLog')), { ...admin, parameters: pageQuery }) },
    '/admin/audit-logs': { get: operation('listAuditLogs', 'Read administrator audit logs', page(ref('AdminAuditLog')), { ...admin, parameters: pageQuery }) },
    ...webhookPaths('api'),
    ...accountSessionPaths(),
  };
  const described = describePaths(paths, { security: [{ sessionToken: [] }], errors: ['UnauthorizedSession', 'RateLimitedSession'] });
  return { openapi: '3.1.0', info: specInfo('HPC Mail Session and Administration API',
    `JWT session API for all web-client functions. Authorization: Bearer <JWT> from login/register. hpcm_ API keys cannot authenticate these routes; see the related /v1 specification. Administrator endpoints require an active admin role. If site policy requires 2FA, un-enrolled sessions receive 403 totp_setup_required; /auth/me, logout and /auth/2fa routes remain available to complete setup. Requests already over the per-user limit do not count toward the instance limit. Every response carries X-Request-ID; ${clientRequestIdRule}.`),
    servers: [{ url: `${origin}/api` }], security: [{ sessionToken: [] }],
    externalDocs: { description: 'Agent usage guide and workflows', url: `${origin}/skill.md` },
    'x-relatedApis': [{ url: `${origin}/v1/openapi.json`, description: 'Scoped API-key mail/mailbox automation' }],
    tags: [{ name: 'Mail', description: 'Session, mail, mailbox and personal preferences' }, { name: 'Administration', description: 'Administrator role required; no API-key scopes grant this role.' }],
    components: { securitySchemes: {
      sessionToken: { type: 'http', scheme: 'bearer', bearerFormat: 'JWT' },
      attachmentSignature: { type: 'apiKey', in: 'query', name: 'sig' }, attachmentExpiry: { type: 'apiKey', in: 'query', name: 'exp' },
    }, schemas: usedSchemas(described), examples: usedExamples(described, origin, '/api') }, paths: described,
  };
}
